INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷112·太祖本纪三·广顺二年正月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44575c9b45f3f29cba05ba49f0a7a9dc69fba5f3/content/books/zizhi-tongjian/vol-290/year-0952/part-01/sources/library/jiuwudaishi-112-january-952/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺二年正月，段落 jiu-wudaishi-205deb4a7860-p002669；已核上下文及传主，纸本及异文待核。", "id": "1868d873-d8eb-51f9-94b9-48809b88b2cf"}, {"title": "资治通鉴·卷290·广顺二年·正月起及相邻追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44575c9b45f3f29cba05ba49f0a7a9dc69fba5f3/content/books/zizhi-tongjian/vol-290/year-0952/part-01/sources/library/tongjian-290-952-january-continuation/source.txt", "note": "《资治通鉴》卷290·广顺二年·正月起及相邻追述，段落 zizhi-tongjian-a63549944a71-p003450；已核上下文及传主，纸本及异文待核。", "id": "937a0bab-01af-5f8d-90b3-d3d0aac5e04b"}, {"title": "新五代史·卷11·周本纪·广顺二年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44575c9b45f3f29cba05ba49f0a7a9dc69fba5f3/content/books/zizhi-tongjian/vol-290/year-0952/part-01/sources/library/xinwudaishi-011-second-year-952/source.txt", "note": "《新五代史》卷11·周本纪·广顺二年，段落 xin-wudaishi-b08f244b9241-p000369；已核上下文及传主，纸本及异文待核。", "id": "1e6a3f71-4a0a-5dc5-9317-801e06108ed1"}, {"title": "资治通鉴·卷290·广顺元年末至二年初·授任征赋与年界", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/05c8382e0d397e9dac6d60dfa83048d6aa2e8137/content/books/zizhi-tongjian/vol-290/year-0951/part-11/sources/library/tongjian-290-951-final-appointments/source.txt", "note": "《资治通鉴》卷290·广顺元年末至二年初·授任征赋与年界，段落 zizhi-tongjian-a63549944a71-p003449；已核上下文及传主，纸本及异文待核。", "id": "80c4a2f1-88c0-5f6d-a274-6602daf65fbb"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "孙朗", "aliases": ["孫朗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "原随蒙城镇将咸师朗投降南唐的军人，后任奉节指挥使。南唐取湖南后因功赏和粮赐问题不满，与曹进商议杀王绍颜、边镐，夺取湖南归附中原。实际起事在952年另段，不提前录为951年既成事实。生卒年未载。", "biography": null, "status": "draft", "id": "becfbb42-fad5-53c5-ab22-fbcbaad91d0d"}, {"name": "曹进", "aliases": ["曹進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐奉节指挥使，原随咸师朗降唐。因功赏、粮赐问题，与孙朗商议杀王绍颜和边镐、夺湖南归附中原。此处为计划，实际起事另见952年。生卒年未载。", "biography": null, "status": "draft", "id": "8b8bc9ad-b3fa-5fbf-9fe9-2287b2a8811d"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "曹英", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周侍卫步军都指挥使、昭武节度使。952年正月任兖州行营都部署，率兵讨伐慕容彦超。生卒年未载。", "biography": null, "status": "draft", "id": "8f85ae9d-3f63-515d-ad74-202e56f02e70"}, {"name": "史延超（后周齐州防御使）", "aliases": ["史延超", "史延韬", "史延韜"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周齐州防御使。952年正月与曹英等受命讨伐慕容彦超，任副部署。《旧五代史》同日同职写史延韬，按对应任命记录别名；与守晋州的史彦超分开。生卒年未载。", "biography": null, "status": "draft", "id": "992ebcad-cc8c-512b-87db-d135293db00c"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "药元福", "aliases": ["藥元福"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州晋阳人，早年侍奉王檀及后唐，曾任深州刺史。945年任后晋马军右厢副排阵使，在白团卫村被围时主张逆风急击，与符彦卿、张彦泽、皇甫遇领骑兵出战。《宋史》还记他战后任威州刺史。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "9bbd6971-3005-5379-8428-512e90ae87d6"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "张令彬", "aliases": ["張令彬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周徐州巡检使，《旧五代史》称徐州巡检供给官。952年正月在沐阳击败南唐援军，并俘获燕敬权等。生卒年未载。", "biography": null, "status": "draft", "id": "63b85da1-7355-52e8-8304-523d3f433bef"}, {"name": "燕敬权", "aliases": ["燕敬權"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。952年正月南唐援慕容彦超的军队在沐阳被后周军击败时被俘。出生、死亡年份未载。", "biography": null, "status": "draft", "id": "e4a3c913-2900-59a5-8cfa-cf946a3458af"}, {"name": "李洪信", "aliases": ["李洪信（保义节度使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李业的兄长，950年任保义节度使。李业逃到陕州时，他不敢把李业藏在自己家中。生卒年未载。", "biography": null, "status": "draft", "id": "f7765562-57e3-5ab1-943b-817dd4ecb0bf"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "孙朗、曹进夜间起事，潜烧府门未能点燃", "start_year": 952, "end_year": 952, "time_original": "952年正月庚申夜", "dynasty": "五代十国", "description": "孙朗、曹进夜间起事，潜烧府门未能点燃。", "phases": [], "location_name": "长沙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7bbd0be8-d070-5092-80dd-d7ab5f951140"}, {"title": "边镐发现起事后出兵交战，并命人鸣鼓角", "start_year": 952, "end_year": 952, "time_original": "952年正月庚申夜", "dynasty": "五代十国", "description": "边镐发现起事后出兵交战，并命人鸣鼓角。", "phases": [], "location_name": "长沙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f0edf805-b5d9-5e47-a0aa-3064553f917e"}, {"title": "孙朗、曹进误以为天将亮，破关逃往朗州", "start_year": 952, "end_year": 952, "time_original": "952年正月庚申起事以后", "dynasty": "五代十国", "description": "孙朗、曹进误以为天将亮，破关逃往朗州。", "phases": [], "location_name": "长沙至朗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e270460b-35da-5cdd-8579-9fca4ebd8732"}, {"title": "王逵向孙朗询问用朗州兵夺回湖南是否可行", "start_year": 952, "end_year": 952, "time_original": "952年正月孙朗到朗州之后", "dynasty": "五代十国", "description": "王逵向孙朗询问用朗州兵夺回湖南是否可行。", "phases": [], "location_name": "朗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2ec74076-423c-5fd0-b8a3-8072d77d3020"}, {"title": "孙朗批评南唐军政，愿为王逵前驱，王逵厚待他", "start_year": 952, "end_year": 952, "time_original": "952年正月王逵问策之后", "dynasty": "